from __future__ import annotations

import re
from dataclasses import dataclass


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)"
    r"\.(0|[1-9][0-9]*)"
    r"\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise TypeError("version must be a string")

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    major, minor, patch = (
        int(match.group(1)),
        int(match.group(2)),
        int(match.group(3)),
    )
    prerelease = tuple(match.group(4).split(".")) if match.group(4) else ()
    build = tuple(match.group(5).split(".")) if match.group(5) else ()

    for identifier in prerelease:
        if (
            identifier.isdigit()
            and len(identifier) > 1
            and identifier[0] == "0"
        ):
            raise ValueError(
                f"invalid version: numeric pre-release identifier "
                f"{identifier!r} has a leading zero"
            )

    return Version(major, minor, patch, prerelease, build)


def _coerce(version: str | Version) -> Version:
    return version if isinstance(version, Version) else parse(version)


def _compare_prerelease(
    a: tuple[str, ...], b: tuple[str, ...]
) -> int:
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1

    for left, right in zip(a, b):
        if left == right:
            continue

        left_numeric = left.isdigit()
        right_numeric = right.isdigit()

        if left_numeric and right_numeric:
            return -1 if int(left) < int(right) else 1
        if left_numeric:
            return -1
        if right_numeric:
            return 1
        return -1 if left < right else 1

    if len(a) == len(b):
        return 0
    return -1 if len(a) < len(b) else 1


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left = _coerce(a)
    right = _coerce(b)

    for attr in ("major", "minor", "patch"):
        left_part = getattr(left, attr)
        right_part = getattr(right, attr)
        if left_part != right_part:
            return -1 if left_part < right_part else 1

    return _compare_prerelease(left.prerelease, right.prerelease)


def _parse_comparator(token: str) -> tuple[str, Version]:
    for operator in (">=", "<=", ">", "<", "=", "^", "~"):
        if token.startswith(operator):
            rest = token[len(operator) :]
            break
    else:
        operator = ""
        rest = token

    if not rest:
        raise ValueError(f"invalid comparator: {token!r}")

    try:
        version = parse(rest)
    except ValueError:
        raise ValueError(f"invalid comparator: {token!r}") from None

    return operator, version


def _parse_range(range_: str) -> list[list[tuple[str, Version]]]:
    if not isinstance(range_, str):
        raise TypeError("range must be a string")

    comparator_sets = []
    for part in range_.split("||"):
        tokens = part.split()
        if not tokens:
            raise ValueError(f"invalid range: {range_!r}")
        comparator_sets.append(
            [_parse_comparator(token) for token in tokens]
        )

    return comparator_sets


def _comparator_holds(operator: str, version: Version, target: Version) -> bool:
    result = compare(version, target)

    if operator in ("", "="):
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    if operator == "<=":
        return result <= 0

    if operator == "^":
        if result < 0:
            return False
        if target.major != 0:
            upper = Version(target.major + 1, 0, 0)
        elif target.minor != 0:
            upper = Version(0, target.minor + 1, 0)
        else:
            upper = Version(0, 0, target.patch + 1)
        return compare(version, upper) < 0

    if operator == "~":
        if result < 0:
            return False
        upper = Version(target.major, target.minor + 1, 0)
        return compare(version, upper) < 0

    raise ValueError(f"unknown comparator operator: {operator!r}")


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _coerce(version)
    comparator_sets = _parse_range(range_)

    for comparators in comparator_sets:
        if candidate.prerelease:
            allowed = any(
                target.prerelease
                and target.major == candidate.major
                and target.minor == candidate.minor
                and target.patch == candidate.patch
                for _, target in comparators
            )
            if not allowed:
                continue

        if all(
            _comparator_holds(operator, candidate, target)
            for operator, target in comparators
        ):
            return True

    return False

from __future__ import annotations

import re
from datetime import date, datetime, timedelta


_MONTH_NAMES = {
    name: index
    for index, name in enumerate(
        ("JAN", "FEB", "MAR", "APR", "MAY", "JUN",
         "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"),
        start=1,
    )
}
_DOW_NAMES = {
    name: index
    for index, name in enumerate(
        ("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT")
    )
}

_NUMBER_RE = re.compile(r"[0-9]+")

# (name, minimum, maximum, names)
_FIELDS = (
    ("minute", 0, 59, None),
    ("hour", 0, 23, None),
    ("day of month", 1, 31, None),
    ("month", 1, 12, _MONTH_NAMES),
    ("day of week", 0, 7, _DOW_NAMES),
)


def _parse_value(
    token: str,
    minimum: int,
    maximum: int,
    names: dict[str, int] | None,
    field: str,
) -> int:
    value = None
    if names is not None:
        value = names.get(token.upper())

    if value is None:
        if _NUMBER_RE.fullmatch(token) is None:
            raise ValueError(f"invalid value {token!r} in {field} field")
        value = int(token)

    if not minimum <= value <= maximum:
        raise ValueError(
            f"value {value} out of range in {field} field "
            f"({minimum}-{maximum})"
        )
    return value


def _parse_field(
    text: str,
    minimum: int,
    maximum: int,
    names: dict[str, int] | None,
    field: str,
    sunday_is_seven: bool = False,
) -> set[int]:
    if not text:
        raise ValueError(f"empty {field} field")

    values: set[int] = set()

    for item in text.split(","):
        if not item:
            raise ValueError(f"malformed item in {field} field")

        if "/" in item:
            base, _, step_text = item.partition("/")
            if "/" in step_text or _NUMBER_RE.fullmatch(step_text) is None:
                raise ValueError(f"malformed item {item!r} in {field} field")
            step = int(step_text)
            if step <= 0:
                raise ValueError(
                    f"step must be positive in {field} field"
                )
            has_step = True
        else:
            base = item
            step = 1
            has_step = False

        if base == "*":
            start, end = minimum, maximum
        elif "-" in base:
            start_text, separator, end_text = base.partition("-")
            if not separator or not start_text or not end_text or "-" in end_text:
                raise ValueError(
                    f"malformed item {item!r} in {field} field"
                )
            start = _parse_value(
                start_text, minimum, maximum, names, field
            )
            end = _parse_value(end_text, minimum, maximum, names, field)
            if start > end:
                raise ValueError(
                    f"range start is after its end in {field} field"
                )
        else:
            start = _parse_value(base, minimum, maximum, names, field)
            if not has_step:
                values.add(0 if sunday_is_seven and start == 7 else start)
                continue
            end = maximum

        for value in range(start, end + 1, step):
            values.add(0 if sunday_is_seven and value == 7 else value)

    return values


def _parse_expression(
    expression: str,
) -> tuple[set[int], set[int], set[int], set[int], set[int], bool, bool]:
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(
            "cron expression must have exactly five fields"
        )

    parsed = []
    for text, (field, minimum, maximum, names) in zip(fields, _FIELDS):
        parsed.append(
            _parse_field(
                text,
                minimum,
                maximum,
                names,
                field,
                sunday_is_seven=(field == "day of week"),
            )
        )

    minute, hour, day_of_month, month, day_of_week = parsed
    return (
        minute,
        hour,
        day_of_month,
        month,
        day_of_week,
        fields[2] != "*",
        fields[4] != "*",
    )


def _add_years(moment: datetime, years: int) -> datetime:
    try:
        return moment.replace(year=moment.year + years)
    except ValueError:
        # February 29 in a year that is not a leap year.
        return moment.replace(year=moment.year + years, day=28)


def _day_matches(
    day: date,
    day_of_month: set[int],
    day_of_week: set[int],
    dom_restricted: bool,
    dow_restricted: bool,
) -> bool:
    dom_match = day.day in day_of_month
    dow_match = (day.weekday() + 1) % 7 in day_of_week

    if dom_restricted and dow_restricted:
        return dom_match or dow_match
    return dom_match and dow_match


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    (
        minutes,
        hours,
        days_of_month,
        months,
        days_of_week,
        dom_restricted,
        dow_restricted,
    ) = _parse_expression(expression)

    limit = _add_years(after, 5)
    current = after.date()
    last_day = limit.date()
    tzinfo = after.tzinfo

    while current <= last_day:
        if current.month in months and _day_matches(
            current,
            days_of_month,
            days_of_week,
            dom_restricted,
            dow_restricted,
        ):
            for hour in sorted(hours):
                for minute in sorted(minutes):
                    candidate = datetime(
                        current.year,
                        current.month,
                        current.day,
                        hour,
                        minute,
                        tzinfo=tzinfo,
                    )
                    if candidate > limit:
                        break
                    if candidate > after:
                        return candidate

        current += timedelta(days=1)

    raise ValueError(
        f"no run for cron expression {expression!r} "
        f"within five years of {after!s}"
    )

