from __future__ import annotations

import re


_DELIMITER_RE = re.compile(r":?-+:?")
_ALIGNMENTS = (None, "left", "right", "center")


def _cell_text(value) -> str:
    text = "" if value is None else str(value)
    return text.replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    missing = width - len(text)
    if alignment == "right":
        return " " * missing + text
    if alignment == "center":
        left = missing // 2
        right = missing - left
        return " " * left + text + " " * right
    return text + " " * missing


def _delimiter(width: int, alignment: str | None) -> str:
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)

    if align is None:
        alignments: list[str | None] = [None] * columns
    else:
        alignments = list(align)
        if len(alignments) != columns:
            raise ValueError(
                "align must have one entry per column"
            )
        for alignment in alignments:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    prepared_rows = []
    for row in rows:
        if len(row) > columns:
            raise ValueError(
                "row has more cells than the header"
            )
        prepared_rows.append([_cell_text(value) for value in row])

    header_cells = [_cell_text(value) for value in header]
    widths = []
    for index in range(columns):
        width = len(header_cells[index])
        for row in prepared_rows:
            if index < len(row):
                width = max(width, len(row[index]))
        widths.append(max(width, 3))

    if columns == 0:
        return ""

    lines = [
        "| "
        + " | ".join(
            _pad(header_cells[index], widths[index], alignments[index])
            for index in range(columns)
        )
        + " |"
    ]
    lines.append(
        "| "
        + " | ".join(
            _delimiter(widths[index], alignments[index])
            for index in range(columns)
        )
        + " |"
    )

    for source in prepared_rows:
        cells = []
        for index in range(columns):
            text = source[index] if index < len(source) else ""
            cells.append(_pad(text, widths[index], alignments[index]))
        lines.append("| " + " | ".join(cells) + " |")

    return "\n".join(lines)


def _split_cells(line: str) -> list[str]:
    text = line.strip()

    if text.startswith("|"):
        text = text[1:]

    if (
        text.endswith("|")
        and not (len(text) >= 2 and text[-2] == "\\")
    ):
        text = text[:-1]

    cells = []
    current = []
    index = 0
    while index < len(text):
        character = text[index]
        if (
            character == "\\"
            and index + 1 < len(text)
            and text[index + 1] == "|"
        ):
            current.append("|")
            index += 2
        elif character == "|":
            cells.append("".join(current).strip())
            current = []
            index += 1
        else:
            current.append(character)
            index += 1

    cells.append("".join(current).strip())
    return cells


def _parse_delimiter(cell: str) -> str | None:
    if _DELIMITER_RE.fullmatch(cell) is None:
        raise ValueError(f"invalid delimiter cell: {cell!r}")

    left = cell.startswith(":")
    right = cell.endswith(":")
    if left and right:
        return "center"
    if left:
        return "left"
    if right:
        return "right"
    return None


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("not a table")

    header = _split_cells(lines[0])
    delimiter_cells = _split_cells(lines[1])

    if len(delimiter_cells) != len(header):
        raise ValueError(
            "delimiter line has a different number of cells than the header"
        )

    alignments = [_parse_delimiter(cell) for cell in delimiter_cells]

    rows = []
    for line in lines[2:]:
        cells = _split_cells(line)
        if len(cells) != len(header):
            raise ValueError(
                "row has a different number of cells than the header"
            )
        rows.append(cells)

    return header, rows, alignments

