from __future__ import annotations


class ParseError(ValueError):
    def __init__(self, lineno: int, message: str):
        super().__init__(f"line {lineno}: {message}")
        self.lineno = lineno


class InterpolationError(ValueError):
    pass


def _reference_value(
    reference: str,
    section: str,
    values: dict[str, dict[str, str]],
    resolve,
) -> str:
    if ":" in reference:
        target_section, target_key = reference.split(":", 1)
    else:
        target_section = section
        target_key = reference

    target_key = target_key.lower()

    if (
        target_section not in values
        or target_key not in values[target_section]
    ):
        raise InterpolationError(
            f"missing key {target_key!r} in section "
            f"{target_section!r}"
        )

    return resolve(target_section, target_key)


def _interpolate(
    text: str,
    section: str,
    values: dict[str, dict[str, str]],
    resolve,
) -> str:
    pieces = []
    index = 0

    while index < len(text):
        character = text[index]

        if character != "$":
            pieces.append(character)
            index += 1
            continue

        if index + 1 < len(text) and text[index + 1] == "$":
            pieces.append("$")
            index += 2
            continue

        if index + 1 < len(text) and text[index + 1] == "{":
            end = text.find("}", index + 2)
            if end != -1:
                reference = text[index + 2 : end]
                pieces.append(
                    _reference_value(reference, section, values, resolve)
                )
                index = end + 1
                continue

        pieces.append("$")
        index += 1

    return "".join(pieces)


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    values: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    current_key: str | None = None

    for lineno, raw_line in enumerate(text.splitlines(), start=1):
        stripped = raw_line.strip()

        if not stripped or stripped[0] in "#;":
            current_key = None
            continue

        if current_key is not None and raw_line[:1].isspace():
            assert current_section is not None
            values[current_section][current_key] += "\n" + stripped
            continue

        current_key = None

        if stripped.startswith("[") and stripped.endswith("]"):
            current_section = stripped[1:-1].strip()
            values.setdefault(current_section, {})
            continue

        equals = stripped.find("=")
        colon = stripped.find(":")
        positions = [position for position in (equals, colon) if position >= 0]

        if not positions:
            raise ParseError(lineno, "unrecognized line")

        split_at = min(positions)
        key = stripped[:split_at].strip().lower()
        value = stripped[split_at + 1 :].strip()

        if not key:
            raise ParseError(lineno, "empty key")

        if current_section is None:
            raise ParseError(lineno, "key outside of a section")

        values[current_section][key] = value
        current_key = key

    memo: dict[tuple[str, str], str] = {}

    def resolve(section: str, key: str, stack=()) -> str:
        node = (section, key)
        if node in memo:
            return memo[node]
        if node in stack:
            raise InterpolationError(
                f"circular reference involving {key!r} in {section!r}"
            )

        result = _interpolate(
            values[section][key],
            section,
            values,
            lambda target_section, target_key: resolve(
                target_section, target_key, stack + (node,)
            ),
        )
        memo[node] = result
        return result

    return {
        section: {
            key: resolve(section, key)
            for key in section_values
        }
        for section, section_values in values.items()
    }

